/// <summary>
/// The <c>AVATraverseRegalvanizationController</c> class is the controller class for <c>Creating contact persons based on GAB</c>
/// </summary>
class AVATraverseRegalvanizationController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///     AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super(classStr(AVATraverseRegalvanizationService), methodStr(AVATraverseRegalvanizationService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// construct method of class
/// </summary>
/// <param name = "_executionMode">SysOperationExecutionMode, default SysOperationExecutionMode::Synchronous</param>
/// <returns>AVATraverseRegalvanizationController</returns>
public static AVATraverseRegalvanizationController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVATraverseRegalvanizationController controller;
    controller = new AVATraverseRegalvanizationController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    ProdParmReportFinished   prodParmReportFinished = _args.record();
    AVATraverseRegalvanizationController controller;
    AVATraverseRegalvanizationContract   contract;
    controller = AVATraverseRegalvanizationController::construct();
    contract = controller.getDataContractObject();
    contract.parmProdId(prodParmReportFinished.ProdId);
    contract.parmTraverseNum(prodParmReportFinished.AVATraverseNum);
    contract.parmReportFinishedParmId(prodParmReportFinished.ParmId);
    controller.parmArgs(_args);
    controller.startOperation();
}
